-- 1) 세차하러 가지 않는 곳 빼기 (전국). 주유소·충전소, 이름에 셀프세차·노터치·디테일링·워시가 있는 곳은 남김
update public.places p set status = 'closed', reject_reason = case
    when p.name ~* '현대자동차|기아자동차|기아오토큐|오토큐|블루핸즈|현대모비스|한국지엠|한국GM|지엠대우|GM대우|쉐보레|르노|쌍용자동차|KG모빌리티|렉서스|토요타|도요타|벤츠|메르세데스|BMW|비엠더블유|아우디|폭스바겐|볼보|포르쉐|재규어|랜드로버|혼다|닛산|인피니티|포드|링컨|지프|캐딜락|테슬라|푸조|마세라티|벤틀리|페라리|람보르기니|한성자동차|코오롱모터스|쎈타|쎈터|T-?Station|Motors|아우토|검사소|대리점|자동차\s*서비스|오토모빌|모빌리티|서비스센터|서비스센타|서비스프라자|지정서비스|직영서비스|정비|공업사|카센터|카센타|모터스|공임나라|스피드메이트|애니카|오토오아시스|카포스|티스테이션|T스테이션|타이어|넥센|판금|도장' then '제외: 정비소·자동차 매장·타이어'
    when p.name ~ '렌트|렌터카|렌탈' and p.name !~ '세차' then '제외: 렌터카'
    when p.type in ('wash','etc','hand') and p.name ~ '사업소|차고지|차량기지|구청|시청|군청|소방서|경찰서|우체국|물류|교통공사|도시공사|철도|도로공사|공단|환경|청소' and p.name !~ '세차' then '제외: 관공서·사업소'
    else '제외: 카써비스(정비)' end
where p.source = 'public_data' and p.status = 'approved'
  and p.type in ('wash','etc','hand','auto')
  and not exists (select 1 from ppx_checked c where c.ref = p.source_ref)
  and p.name !~* '주유소|충전소|주유|오일뱅크|칼텍스|S-?OIL|에스오일|에너지|셀프세차|노터치|디테일링'
  and p.name !~* '워시|wash'
  and ( p.name ~* '현대자동차|기아자동차|기아오토큐|오토큐|블루핸즈|현대모비스|한국지엠|한국GM|지엠대우|GM대우|쉐보레|르노|쌍용자동차|KG모빌리티|렉서스|토요타|도요타|벤츠|메르세데스|BMW|비엠더블유|아우디|폭스바겐|볼보|포르쉐|재규어|랜드로버|혼다|닛산|인피니티|포드|링컨|지프|캐딜락|테슬라|푸조|마세라티|벤틀리|페라리|람보르기니|한성자동차|코오롱모터스|쎈타|쎈터|T-?Station|Motors|아우토|검사소|대리점|자동차\s*서비스|오토모빌|모빌리티|서비스센터|서비스센타|서비스프라자|지정서비스|직영서비스|정비|공업사|카센터|카센타|모터스|공임나라|스피드메이트|애니카|오토오아시스|카포스|티스테이션|T스테이션|타이어|넥센|판금|도장'
     or (p.name ~ '렌트|렌터카|렌탈' and p.name !~ '세차')
     or (p.type in ('wash','etc','hand') and p.name ~ '사업소|차고지|차량기지|구청|시청|군청|소방서|경찰서|우체국|물류|교통공사|도시공사|철도|도로공사|공단|환경|청소' and p.name !~ '세차')
     or (p.type in ('wash','etc') and p.name ~ '카\s*써비스|카\s*서비스|자동차\s*써비스|오토\s*써비스') );

-- 2) 체인점: 컴인워시는 전국 모두 '노터치 + 자동세차', 나머지는 '종류 확인 중'인 지점만
update public.places p set type = 'notouch', types = '{notouch,auto}'
where p.source = 'public_data' and p.status = 'approved' and replace(p.name, ' ', '') like '컴인워시%'
  and not exists (select 1 from ppx_checked c where c.ref = p.source_ref);
update public.places p set type = v.t, types = array[v.t]
from (values ('킹콩샤워','self'), ('디케이워시','notouch'), ('워시존개러지','self'), ('워시나인','detail'), ('유워시','self')) as v(pre, t)
where p.source = 'public_data' and p.status = 'approved' and p.type = 'wash'
  and replace(p.name, ' ', '') like v.pre || '%'
  and not exists (select 1 from ppx_checked c where c.ref = p.source_ref);

